52: /// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
53: fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
54:     if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
55:         return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
56:     }
57:     let t = 0.5 * (ray.direction.unit().y + 1.0);
58:     Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
59: }
