76: /// Every pixel's colour, row by row from the top, averaging `samples` rays per pixel. Reports the
77: /// share of rows done on standard error.
78: fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
79:     let world = scene();
80:     let camera = Camera::new(width as f64 / height as f64);
81:     let mut pixels = Vec::with_capacity(width * height);
82:     for row in (0..height).rev() {
83:         for column in 0..width {
84:             let u = column as f64 / (width - 1) as f64;
85:             let v = row as f64 / (height - 1) as f64;
86:             let ray = camera.ray(u, v);
87:             let mut colour = Colour::new(0.0, 0.0, 0.0);
88:             for _ in 0..samples {
89:                 colour = colour + ray_colour(&ray, &world);
90:             }
91:             pixels.push(colour / samples as f64);
92:         }
93:         eprint!("\r{} of {} rows", height - row, height);
94:     }
95:     eprintln!();
96:     pixels
97: }
