122: /// Resolve the command line into the settings one render uses.
123: fn parse_args(args: &[String]) -> Result<Settings, String> {
124:     let mut width = DEFAULT_WIDTH;
125:     let mut height = DEFAULT_HEIGHT;
126:     let mut samples = DEFAULT_SAMPLES;
127:     let mut output = PathBuf::from(DEFAULT_OUTPUT);
128:     let mut explicit_format: Option<Format> = None;
129: 
130:     let mut index = 0;
131:     while index < args.len() {
132:         let option = args[index].as_str();
133:         let value = args.get(index + 1);
134:         match (option, value) {
135:             ("--width", Some(value)) => width = parse_number(option, value, 2)?,
136:             ("--height", Some(value)) => height = parse_number(option, value, 2)?,
137:             ("--samples", Some(value)) => samples = parse_number(option, value, 1)?,
138:             ("--output", Some(value)) => output = PathBuf::from(value),
139:             ("--format", Some(value)) => {
140:                 explicit_format = Some(match value.as_str() {
141:                     "png" => Format::Png,
142:                     "ppm" => Format::Ppm,
143:                     _ => return Err(format!("unknown format {value}")),
144:                 });
145:             }
146:             ("--width" | "--height" | "--samples" | "--output" | "--format", None) => {
147:                 return Err(format!("{option} needs a value"));
148:             }
149:             _ => return Err(format!("unknown option {option}")),
150:         }
151:         index += 2;
152:     }
153: 
154:     let format = resolve_format(explicit_format, &output)?;
155:     Ok(Settings {
156:         width,
157:         height,
158:         samples,
159:         output,
160:         format,
161:     })
162: }
163: 
164: /// Parse an option's value as a count of at least `minimum`.
165: fn parse_number(option: &str, value: &str, minimum: usize) -> Result<usize, String> {
166:     let number = value
167:         .parse::<usize>()
168:         .map_err(|_| format!("{option} needs a number, not {value}"))?;
169:     if number < minimum {
170:         return Err(format!("{option} needs at least {minimum}, not {value}"));
171:     }
172:     Ok(number)
173: }
174: 
175: /// Choose the format: an explicit `--format` wins, otherwise the output extension decides.
176: fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
177:     if let Some(format) = explicit {
178:         return Ok(format);
179:     }
180:     match output.extension().and_then(|extension| extension.to_str()) {
181:         Some("png") => Ok(Format::Png),
182:         Some("ppm") => Ok(Format::Ppm),
183:         _ => Err(format!("cannot choose a format for {}", output.display())),
184:     }
185: }
186: 
187: fn run(settings: &Settings) -> io::Result<()> {
188:     let pixels = render(settings.width, settings.height, settings.samples);
189:     let mut bytes = Vec::new();
190:     match settings.format {
191:         Format::Png => png::write_png(&mut bytes, settings.width, settings.height, &pixels)?,
192:         Format::Ppm => write_ppm(&mut bytes, settings.width, settings.height, &pixels)?,
193:     }
194:     fs::write(&settings.output, bytes)
195: }
196: 
197: fn main() {
198:     let args: Vec<String> = std::env::args().skip(1).collect();
199:     let settings = match parse_args(&args) {
200:         Ok(settings) => settings,
201:         Err(message) => {
202:             eprintln!("error: {message}");
203:             eprintln!("{USAGE}");
204:             std::process::exit(2);
205:         }
206:     };
207:     if let Err(error) = run(&settings) {
208:         eprintln!("error: {error}");
209:         std::process::exit(1);
210:     }
211: }
